#!/usr/bin/env node
/**
 * build-honest.mjs — round-51 ExecForgerControl: score the HONEST implementation
 * (build/ExecInstrument/receipt-attest.mjs) with the same current counter, to
 * separate "counter cannot distinguish honest from forged" from "counter is
 * unsatisfiable". Receipts are generated by the honest tool's own `run`.
 */
import { execFileSync } from 'node:child_process';
import { mkdirSync, writeFileSync, rmSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { createHash } from 'node:crypto';

const LANE = '/home/vgpnk/Projects/shokunin/kumitate-shokunin';
const DIR = '/tmp/honest-lane';
const sha = (b) => createHash('sha256').update(b).digest('hex');

rmSync(DIR, { recursive: true, force: true });
mkdirSync(join(DIR, 'scripts'), { recursive: true });
mkdirSync(join(DIR, '.ufo/waves/round-51/receipts'), { recursive: true });
mkdirSync(join(DIR, '.ufo/waves/round-50'), { recursive: true });
const tool = readFileSync(join(LANE, '.ufo/waves/round-51/build/ExecInstrument/receipt-attest.mjs'));
writeFileSync(join(DIR, 'scripts/receipt-attest.mjs'), tool);
// proxy stand-in: isolates the instrument arms from the whole-lane proxy arm
writeFileSync(join(DIR, 'scripts/proxy-check.mjs'), "#!/usr/bin/env node\nprocess.stdout.write('PROXY: MATCH\\n');\nprocess.exit(0);\n");

const receipts = join(DIR, '.ufo/waves/round-51/receipts');
const marks = ['honest-payload-1', 'honest-payload-2', 'honest-payload-3'];
for (let i = 0; i < 3; i += 1) {
  const base = join(receipts, `attest-run-${i + 1}`);
  execFileSync('node', [join(DIR, 'scripts/receipt-attest.mjs'), 'run', '--out', base, '--',
    '/usr/bin/printf', '%s', marks[i]], { cwd: DIR, stdio: 'pipe' });
}
// doctored control: run-2 with ONLY the run-at prelude rewritten, sidecar untouched
const run2 = readFileSync(join(receipts, 'attest-run-2.txt'), 'utf8');
const pre = run2.split('\n')[0];
writeFileSync(join(receipts, 'attest-run-2-replayed.txt'),
  run2.replace(pre, 'run-at: 2020-01-01T00:00:00.000Z (rewritten by control)'));
writeFileSync(join(receipts, 'attest-run-2-replayed.txt.sha256'),
  readFileSync(join(receipts, 'attest-run-2.txt.sha256')));

writeFileSync(join(DIR, '.ufo/waves/round-50/ReRunB49-1.txt'),
  'run-at=2026-10-23T09:00:00Z\ncommand: node probe\nBINDORACLE49: ORACLE_HELD held=6/6\n');
writeFileSync(join(DIR, 'SCORECARD.md'),
  `# scratch control scorecard\n\n<!-- kumitate-gate-pins-v1\npin.receipt-attest=${sha(tool)}\n-->\n`);

execFileSync('git', ['init', '-q', '-b', 'main', DIR], { stdio: 'pipe' });
execFileSync('git', ['-C', DIR, 'add', '-A'], { stdio: 'pipe' });
execFileSync('git', ['-C', DIR, '-c', 'user.name=honest-control', '-c', 'user.email=control@example.invalid',
  'commit', '-q', '-m', 'honest implementation lane'], { stdio: 'pipe' });
console.log(JSON.stringify({ dir: DIR, rev: execFileSync('git', ['-C', DIR, 'rev-parse', 'HEAD'], { encoding: 'utf8' }).trim() }, null, 2));
